// workers/sector-slow/src/signing.js
//
// Ed25519 signing for correlation snapshots.
//
// Used to prove that a snapshot existed at a specific time, unmodified.
// Produces: { ...snapshot, signature: "base64...", pubkey_id: "..." }
//
// Not yet wired into index.js. Wiring is Nov 7+, after 3 days of
// cron-written snapshots exist so the first signed genesis is on
// verified data, not manual ?snapshot=1 writes.
//
// Key format (stored in Cloudflare Secrets as VOLATIAI_SIGNING_KEY):
//   - PKCS8 DER, base64-encoded
//   - Generated by: crypto.generateKeyPairSync('ed25519') → privateKey.export('pkcs8', 'der')
//
// Public key served at /.well-known/volatiai-pubkey.pem (Nov 7+)
// Public key also committed to repo: workers/sector-slow/volatiai-pubkey.pem

export function base64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes;
}

export function bytesToBase64(bytes) {
  let bin = "";
  for (let i = 0; i < bytes.length; i++) {
    bin += String.fromCharCode(bytes[i]);
  }
  return btoa(bin);
}

// Canonicalize: sort keys recursively, no whitespace. Deterministic for any
// object shape. Two semantically-identical objects produce identical strings.
export function canonicalize(obj) {
  if (obj === null || typeof obj !== "object") {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return "[" + obj.map(canonicalize).join(",") + "]";
  }
  const keys = Object.keys(obj).sort();
  const parts = [];
  for (const k of keys) {
    parts.push(JSON.stringify(k) + ":" + canonicalize(obj[k]));
  }
  return "{" + parts.join(",") + "}";
}

export async function importSigningKey(b64Der) {
  const der = base64ToBytes(b64Der);
  return crypto.subtle.importKey(
    "pkcs8",
    der.buffer,
    { name: "Ed25519" },
    false,
    ["sign"]
  );
}

export async function importVerificationKey(pem) {
  const body = pem
    .replace(/-----BEGIN PUBLIC KEY-----/, "")
    .replace(/-----END PUBLIC KEY-----/, "")
    .replace(/\s+/g, "");
  const der = base64ToBytes(body);
  return crypto.subtle.importKey(
    "spki",
    der.buffer,
    { name: "Ed25519" },
    false,
    ["verify"]
  );
}

/**
 * Sign a snapshot object. Returns the snapshot extended with:
 *   signature    — base64 of Ed25519 signature over canonicalized snapshot
 *   pubkey_id    — human-readable key identifier (for rotation tracking)
 *   signed_at    — ISO timestamp of signing (included in signature)
 *
 * The signature covers all fields of the input snapshot PLUS signed_at.
 * Any modification to any field breaks verification.
 */
export async function signSnapshot(snapshot, env) {
  if (!env || !env.VOLATIAI_SIGNING_KEY) {
    throw new Error("VOLATIAI_SIGNING_KEY not configured in env");
  }
  const key = await importSigningKey(env.VOLATIAI_SIGNING_KEY);

  const toSign = {
    ...snapshot,
    signed_at: new Date().toISOString(),
  };
  const canonical = canonicalize(toSign);
  const data = new TextEncoder().encode(canonical);
  const sigBuffer = await crypto.subtle.sign("Ed25519", key, data);
  const signature = bytesToBase64(new Uint8Array(sigBuffer));

  return {
    ...toSign,
    signature,
    pubkey_id: env.VOLATIAI_PUBKEY_ID || "volatiai-2026-11",
  };
}

/**
 * Verify a signed snapshot against a PEM-encoded Ed25519 public key.
 *
 * Returns:
 *   { valid: true }                                    — signature matches
 *   { valid: false, reason: "no_signature" }           — missing signature field
 *   { valid: false, reason: "no_signed_at" }           — missing signed_at field
 *   { valid: false, reason: "signature_mismatch" }     — data modified or wrong key
 *   { valid: false, reason: "error", message: "..." }  — import/verify failed
 */
export async function verifySnapshot(signed, publicKeyPem) {
  if (!signed || typeof signed !== "object") {
    return { valid: false, reason: "not_an_object" };
  }
  if (!signed.signature) {
    return { valid: false, reason: "no_signature" };
  }
  if (!signed.signed_at) {
    return { valid: false, reason: "no_signed_at" };
  }

  const { signature, pubkey_id, ...rest } = signed;
  const canonical = canonicalize(rest);
  const data = new TextEncoder().encode(canonical);

  try {
    const key = await importVerificationKey(publicKeyPem);
    const sig = base64ToBytes(signature);
    const valid = await crypto.subtle.verify(
      "Ed25519",
      key,
      sig.buffer,
      data
    );
    return valid
      ? { valid: true, pubkey_id: pubkey_id || null, signed_at: signed.signed_at }
      : { valid: false, reason: "signature_mismatch" };
  } catch (e) {
    return { valid: false, reason: "error", message: String(e && e.message || e).slice(0, 120) };
  }
}
